import { useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import {
  CategoryScale,
  Chart as ChartJS,
  Filler,
  Legend,
  LinearScale,
  LineElement,
  PointElement,
  Title,
  Tooltip,
} from 'chart.js';
import { Line } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5001';

const MAX_POINTS = 20;

function Dashboard() {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    let mounted = true;
    const socket = io(API_URL);

    fetch(`${API_URL}/api/alerts`)
      .then((response) => response.json())
      .then((history) => {
        if (mounted && Array.isArray(history)) {
          setAlerts(history.reverse().slice(-MAX_POINTS));
        }
      })
      .catch((error) => console.error('Unable to load alert history:', error));

    socket.on('alert', (alert) => {
      if (mounted) {
        setAlerts((current) => [...current, alert].slice(-MAX_POINTS));
      }
    });

    return () => {
      mounted = false;
      socket.disconnect();
    };
  }, []);

  const chartData = {
    labels: alerts.map((alert) => alert.productID),
    datasets: [
      {
        label: 'Torque (Nm)',
        data: alerts.map((alert) => alert.torque),
        borderColor: '#55d6be',
        backgroundColor: 'rgba(85, 214, 190, 0.12)',
        fill: true,
        tension: 0.35,
      },
      {
        label: 'Tool wear',
        data: alerts.map((alert) => alert.toolWear),
        borderColor: '#f5a65b',
        backgroundColor: 'rgba(245, 166, 91, 0.08)',
        fill: true,
        tension: 0.35,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 350 },
    plugins: {
      legend: { labels: { color: '#a6b4c3', usePointStyle: true } },
      tooltip: { mode: 'index', intersect: false },
    },
    scales: {
      x: { ticks: { color: '#718096' }, grid: { color: 'rgba(166, 180, 195, 0.08)' } },
      y: { ticks: { color: '#718096' }, grid: { color: 'rgba(166, 180, 195, 0.08)' } },
    },
  };

  return (
    <section className="panel dashboard-panel">
      <div className="panel-heading">
        <div>
          <p className="eyebrow">TELEMETRY</p>
          <h2>Machine signal history</h2>
        </div>
        <span className="metric-count">{alerts.length} POINTS</span>
      </div>
      <div className="chart-wrap">
        {alerts.length ? <Line data={chartData} options={chartOptions} /> : <p className="empty-state">Waiting for telemetry...</p>}
      </div>
    </section>
  );
}

export default Dashboard;
